package com.echovault.servlet;import com.echovault.dao.CapsuleDAO;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;@WebServlet("/admin-dashboard") public class AdminDashboardServlet extends HttpServlet{protected void doGet(HttpServletRequest q,HttpServletResponse s)throws ServletException,IOException{HttpSession h=q.getSession(false);if(h==null||h.getAttribute("adminId")==null){s.sendRedirect("admin-login.jsp");return;}try{q.setAttribute("capsules",new CapsuleDAO().all());q.getRequestDispatcher("admin-dashboard.jsp").forward(q,s);}catch(Exception e){throw new ServletException(e);}}}